import{_ as i,c as e,o as t,ag as n}from"./chunks/framework.ymCRTBvy.js";const p=JSON.parse('{"title":"19.3_实现UINavigationController的Push或Pop动画","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/animation/19.3_实现UINavigationController的Push或Pop动画.md","filePath":"uikit/animation/19.3_实现UINavigationController的Push或Pop动画.md"}'),a={name:"uikit/animation/19.3_实现UINavigationController的Push或Pop动画.md"};function l(r,o,d,c,s,u){return t(),e("div",null,o[0]||(o[0]=[n('<h1 id="_19-3-实现uinavigationcontroller的push或pop动画" tabindex="-1">19.3_实现UINavigationController的Push或Pop动画 <a class="header-anchor" href="#_19-3-实现uinavigationcontroller的push或pop动画" aria-label="Permalink to &quot;19.3_实现UINavigationController的Push或Pop动画&quot;">​</a></h1><h2 id="探索uinavigationcontroller的push-pop动画" tabindex="-1">探索UINavigationController的Push/Pop动画 <a class="header-anchor" href="#探索uinavigationcontroller的push-pop动画" aria-label="Permalink to &quot;探索UINavigationController的Push/Pop动画&quot;">​</a></h2><p>在iOS开发中，<code>UINavigationController</code>是管理视图控制器栈的核心组件。它通过Push和Pop操作实现视图控制器之间的切换，而这些切换过程正是我们施展动画魔法的绝佳舞台！✨ 你将学习如何为这些默认的切换添加自定义动画，让你的应用界面焕然一新。</p><h2 id="自定义转场动画的核心协议" tabindex="-1">自定义转场动画的核心协议 <a class="header-anchor" href="#自定义转场动画的核心协议" aria-label="Permalink to &quot;自定义转场动画的核心协议&quot;">​</a></h2><p>要实现自定义的Push/Pop动画，你需要深入理解并实现两个关键协议。它们是<code>UIViewControllerAnimatedTransitioning</code>和<code>UINavigationControllerDelegate</code>。通过它们，你将完全掌控转场动画的每一个细节。</p><ul><li><strong><code>UIViewControllerAnimatedTransitioning</code></strong>: 这个协议定义了动画的实际内容和持续时间。你需要实现它的两个核心方法： <ul><li><code>transitionDuration(using:)</code>：返回动画的持续时间，例如0.5秒。</li><li><code>animateTransition(using:)</code>：这是动画逻辑的核心，你在这里定义视图如何从一个状态过渡到另一个状态。</li></ul></li><li><strong><code>UINavigationControllerDelegate</code></strong>: 这个协议允许你告诉<code>UINavigationController</code>使用你的自定义动画对象。你需要实现<code>navigationController(_:animationControllerFor:from:to:)</code>方法，并在其中返回你的自定义动画对象。</li></ul><h2 id="实现push动画-从无到有" tabindex="-1">实现Push动画：从无到有 <a class="header-anchor" href="#实现push动画-从无到有" aria-label="Permalink to &quot;实现Push动画：从无到有&quot;">​</a></h2><p>让我们以一个Push动画为例，详细讲解实现步骤。想象一下，当一个新视图控制器被推入时，它能从屏幕底部优雅地滑入。这会给用户带来非常流畅的体验！</p><ol><li><strong>创建动画对象</strong>: 首先，你需要创建一个遵循<code>UIViewControllerAnimatedTransitioning</code>协议的类，比如<code>CustomPushAnimator</code>。</li><li><strong>定义动画时长</strong>: 在<code>CustomPushAnimator</code>中，实现<code>transitionDuration(using:)</code>方法，返回你想要的动画时长，例如<code>0.7</code>秒。</li><li><strong>编写动画逻辑</strong>: 在<code>animateTransition(using:)</code>方法中，你将获取到转场上下文（<code>transitionContext</code>）。 <ul><li>获取源视图控制器（<code>fromVC</code>）和目标视图控制器（<code>toVC</code>）的视图。</li><li>将目标视图添加到容器视图（<code>containerView</code>）中。</li><li>设置目标视图的初始位置，例如在屏幕下方。</li><li>使用<code>UIView.animate</code>方法，将目标视图动画到最终位置，同时可以调整源视图的透明度或位置，创造出丰富的视觉效果。</li><li>动画完成后，务必调用<code>transitionContext.completeTransition(true)</code>来通知系统动画已完成。</li></ul></li></ol><h2 id="实现pop动画-优雅地返回" tabindex="-1">实现Pop动画：优雅地返回 <a class="header-anchor" href="#实现pop动画-优雅地返回" aria-label="Permalink to &quot;实现Pop动画：优雅地返回&quot;">​</a></h2><p>Pop动画与Push动画类似，但方向相反。当用户点击返回按钮时，你可以让当前视图控制器优雅地滑出屏幕，而前一个视图控制器则重新出现。</p><ol><li><strong>创建Pop动画对象</strong>: 同样，创建一个遵循<code>UIViewControllerAnimatedTransitioning</code>协议的类，例如<code>CustomPopAnimator</code>。</li><li><strong>定义动画时长</strong>: 在<code>CustomPopAnimator</code>中，设置动画时长，例如<code>0.6</code>秒。</li><li><strong>编写动画逻辑</strong>: 在<code>animateTransition(using:)</code>方法中： <ul><li>获取源视图控制器（当前显示的视图）和目标视图控制器（即将显示的视图）。</li><li>将目标视图插入到容器视图的底部，确保它在源视图的下方。</li><li>设置源视图的最终位置，例如滑出屏幕。</li><li>使用<code>UIView.animate</code>进行动画，将源视图移出屏幕，同时目标视图可以逐渐显现。</li><li>动画结束后，调用<code>transitionContext.completeTransition(true)</code>。</li></ul></li></ol><h2 id="整合到uinavigationcontrollerdelegate" tabindex="-1">整合到UINavigationControllerDelegate <a class="header-anchor" href="#整合到uinavigationcontrollerdelegate" aria-label="Permalink to &quot;整合到UINavigationControllerDelegate&quot;">​</a></h2><p>最后一步是将你的自定义动画对象与<code>UINavigationController</code>关联起来。</p><ol><li><strong>设置代理</strong>: 在你的<code>UINavigationController</code>的代理对象（通常是你的根视图控制器或一个专门的代理类）中，将<code>navigationController.delegate</code>设置为自身。</li><li><strong>实现代理方法</strong>: 实现<code>navigationController(_:animationControllerFor:from:to:)</code>方法。 <ul><li>在这个方法中，你需要判断当前是Push操作还是Pop操作。</li><li>如果是Push，返回你的<code>CustomPushAnimator</code>实例。</li><li>如果是Pop，返回你的<code>CustomPopAnimator</code>实例。</li></ul></li></ol><p>通过这些步骤，你就能为<code>UINavigationController</code>的Push/Pop操作注入生动的自定义动画，让你的应用界面更具吸引力！🚀 这种能力在许多流行的应用中都有体现，例如一些社交媒体应用在切换个人资料页面时会使用独特的转场效果。</p>',16)]))}const h=i(a,[["render",l]]);export{p as __pageData,h as default};
